package com.amit.headroom;
import android.app.PendingIntent;import android.appwidget.AppWidgetManager;import android.appwidget.AppWidgetProvider;import android.content.*;import android.net.Uri;import android.widget.RemoteViews;
public class HeadRoomWidget extends AppWidgetProvider{public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.headroom_widget);Intent service=new Intent(c,HeadRoomWidgetService.class);service.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);service.setData(Uri.parse(service.toUri(Intent.URI_INTENT_SCHEME)));v.setRemoteAdapter(R.id.widgetList,service);v.setEmptyView(R.id.widgetList,R.id.widgetEmpty);try{String json=c.getSharedPreferences("HeadRoomWidget",Context.MODE_PRIVATE).getString("tasks","[]");org.json.JSONArray a=new org.json.JSONArray(json);int active=0,done=0;for(int i=0;i<a.length();i++){if(a.getJSONObject(i).optBoolean("done"))done++;else active++;}v.setTextViewText(R.id.widgetCounts,active+" active • "+done+" completed");}catch(Exception ignored){}Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widgetTitle,PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}}